import{_ as a,C as o,o as n,c as r,ai as i,E as d}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"自动化进阶","description":"例程、技能、多 Bot 分工，把做顺的事交给自动化。","frontmatter":{"title":"自动化进阶","description":"例程、技能、多 Bot 分工，把做顺的事交给自动化。","wordCount":364,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"自动化进阶 | WANGXXXL"}],["meta",{"property":"og:description","content":"例程、技能、多 Bot 分工，把做顺的事交给自动化。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/automation/"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/automation-52fcce7cc1.png"}],["meta",{"property":"og:image:alt","content":"自动化进阶 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"自动化进阶 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"例程、技能、多 Bot 分工，把做顺的事交给自动化。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/automation-52fcce7cc1.png"}],["meta",{"name":"twitter:image:alt","content":"自动化进阶 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/automation/"}]]},"headers":[],"relativePath":"automation/index.md","filePath":"automation/index.md","lastUpdated":1792499451000}'),c={name:"automation/index.md"};function m(l,t,p,s,h,u){const e=o("SectionHub");return n(),r("div",null,[t[0]||(t[0]=i('<h1 id="自动化进阶" tabindex="-1">自动化进阶 <a class="header-anchor" href="#自动化进阶" aria-label="Permalink to &quot;自动化进阶&quot;">​</a></h1><p>自动化的核心是一个顺序：<strong>一次性任务跑通 → 存成技能 → 设成例程 → 需要时再拆成多个 Bot</strong>。不同阶段用不同的工具：</p><table tabindex="0"><thead><tr><th>你的情况</th><th>该用</th><th>看这篇</th></tr></thead><tbody><tr><td>同一件事已经手动做顺了两三次，想让所有 Bot 都按同一套方法做</td><td>技能</td><td><a href="/automation/skills">技能沉淀</a></td></tr><tr><td>想让它每天、每周定时做，或收到消息、通知时自动做</td><td>例程</td><td><a href="/automation/routines">例程：定时与事件触发</a></td></tr><tr><td>一个 Bot 的活太杂，调研、写作、审核混在一起</td><td>多 Bot 分工</td><td><a href="/automation/multi-bot-teamwork">多 Bot 分工协作</a></td></tr><tr><td>想先做一个完整的自动化练手</td><td>照着搭一遍</td><td><a href="/automation/daily-briefing">每日简报类自动化实例</a></td></tr></tbody></table><h2 id="设例程之前先过这-6-项" tabindex="-1">设例程之前先过这 6 项 <a class="header-anchor" href="#设例程之前先过这-6-项" aria-label="Permalink to &quot;设例程之前先过这 6 项&quot;">​</a></h2><p>由哪个 Bot 负责 · 时间和时区 · 数据来源 · 期望结果发到哪里 · 哪些动作需要审批 · 来源缺失时怎么办（明说，不凑数）。</p><p>六项里有一项说不清，就先别自动化，回到手动再跑一次。为什么要这样做、每一步怎么说，见日更：<a href="/daily/2026-10-20-skill-before-routine">先跑通一次，再存技能，最后才设例程</a>。</p><div class="warning custom-block"><p class="custom-block-title">自动化会放大错误</p><p>例程在你不看的时候运行，例程里发起的审批大约 10 分钟没人处理就会过期。写操作（发送、发布、删除）一定放在审批后面，并打开这个 Bot 的通知。</p></div>',7)),d(e,{section:"automation"})])}const _=a(c,[["render",m]]);export{g as __pageData,_ as default};
